package dev.kelmagic.client;
import dev.kelmagic.content.*;import dev.kelmagic.network.InkSelect;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionHand;import net.neoforged.neoforge.network.PacketDistributor;import java.util.*;
public final class InkPatternScreen extends Screen {
 private final InteractionHand hand;private String category="Русский",selected;private int page,left,top;private final List<InkPatterns.Pattern> shown=new ArrayList<>();
 public InkPatternScreen(InteractionHand h){super(Component.literal("Рисунки архивариуса"));hand=h;var p=net.minecraft.client.Minecraft.getInstance().player;selected=p==null?"u2192":InkDrawings.selected(p.getItemInHand(h));}
 @Override protected void init(){left=(width-330)/2;top=(height-228)/2;shown.clear();String[] cats={"Русский","English","Числа","Стрелки","Мобы","Знаки"};for(int i=0;i<cats.length;i++){String c=cats[i];addRenderableWidget(Button.builder(Component.literal(c),b->{category=c;page=0;rebuildWidgets();}).bounds(left+i*55,top+24,54,20).build());}var entries=InkPatterns.ALL.stream().filter(p->p.category().equals(category)).toList();int max=Math.max(0,(entries.size()-1)/40);page=Math.clamp(page,0,max);for(int n=page*40;n<Math.min(entries.size(),(page+1)*40);n++){var pattern=entries.get(n);int j=n-page*40,x=left+6+j%10*32,y=top+54+j/10*32;shown.add(pattern);var button=Button.builder(Component.empty(),b->{selected=pattern.id();PacketDistributor.sendToServer(new InkSelect(hand==InteractionHand.OFF_HAND,selected));if(minecraft.player!=null&&minecraft.player.getItemInHand(hand).is(ArchiveStorage.INK.get()))minecraft.player.getItemInHand(hand).set(dev.kelmagic.MagicComponents.INK_PATTERN.get(),selected);rebuildWidgets();}).bounds(x,y,30,30).tooltip(net.minecraft.client.gui.components.Tooltip.create(Component.literal(InkPatterns.label(pattern)))).build();addRenderableWidget(button);}addRenderableWidget(Button.builder(Component.literal("‹"),b->{page=Math.max(0,page-1);rebuildWidgets();}).bounds(left+8,top+190,28,20).build());addRenderableWidget(Button.builder(Component.literal("›"),b->{page=Math.min(max,page+1);rebuildWidgets();}).bounds(left+294,top+190,28,20).build());addRenderableWidget(Button.builder(Component.literal("Готово"),b->onClose()).bounds(left+126,top+190,78,20).build());}
 @Override public void render(GuiGraphics g,int mx,int my,float t){renderBackground(g,mx,my,t);g.fill(left-5,top-5,left+335,top+232,0xF0332934);g.drawCenteredString(font,title,width/2,top+6,0xFFE4C482);for(var widget:renderables)widget.render(g,mx,my,t);for(int i=0;i<shown.size();i++){var pat=shown.get(i);int x=left+6+i%10*32,y=top+54+i/10*32;g.blit(InkMarkRenderer.ATLAS,x+7,y+7,(pat.tile()%16)*16,(pat.tile()/16)*16,16,16,256,256);if(pat.id().equals(selected))g.renderOutline(x,y,30,30,0xFF6CDCD0);}g.drawCenteredString(font,Component.literal("Выбрано: "+InkPatterns.label(InkPatterns.get(selected))),width/2,top+181,0xFFD6C4A5);}
 @Override public boolean isPauseScreen(){return false;}
}
